"""configloader — tiny .ini-style config parser with typed values."""


def _coerce(raw):
    """Coerce a raw value string to bool/int/float/str per the spec."""
    if len(raw) >= 2 and raw.startswith('"') and raw.endswith('"'):
        return raw[1:-1]
    lowered = raw.lower()
    if lowered == "true":
        return True
    if lowered == "false":
        return False
    try:
        return int(raw)
    except ValueError:
        pass
    try:
        return float(raw)
    except ValueError:
        pass
    return raw


def parse_config(text):
    """Parse config text into a nested dict {section: {key: value}}."""
    config = {}
    section = ""
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#") or line.startswith(";"):
            continue
        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1].strip()
            config.setdefault(section, {})
            continue
        key, sep, value = line.partition("=")
        if not sep:
            continue
        config.setdefault(section, {})[key.strip()] = _coerce(value.strip())
    return config


def get(config, dotted, default=None):
    """Look up "section.key" in a parsed config; return default if absent."""
    section, sep, key = dotted.partition(".")
    if not sep:
        section, key = "", section
    return config.get(section, {}).get(key, default)

